#!/usr/bin/env python3
"""Search the nano-banana UI prompts library.

Usage:
  python3 search.py --query "bento" --category infographic
  python3 search.py --featured
  python3 search.py --category thumbnail --format md
  python3 search.py --id featured-2
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

DATA_PATH = Path(__file__).resolve().parent.parent / "data" / "ui-prompts.json"
CATEGORIES = {"featured", "infographic", "social-media", "thumbnail", "product-marketing", "ecommerce"}


def load() -> dict:
    if not DATA_PATH.exists():
        print(f"error: data file not found at {DATA_PATH}", file=sys.stderr)
        sys.exit(1)
    return json.loads(DATA_PATH.read_text(encoding="utf-8"))


def score_match(prompt: dict, terms: list[str]) -> int:
    haystack = " ".join(
        [
            prompt.get("title", ""),
            prompt.get("description") or "",
            prompt.get("prompt", "")[:500],
        ]
    ).lower()
    return sum(1 for t in terms if t.lower() in haystack)


def filter_prompts(
    prompts: list[dict],
    query: str | None,
    category: str | None,
    featured_only: bool,
    prompt_id: str | None,
    raycast_only: bool,
    limit: int,
) -> list[dict]:
    out = list(prompts)
    if prompt_id:
        out = [p for p in out if p["id"] == prompt_id]
    if category:
        out = [p for p in out if p["category"] == category]
    if featured_only:
        out = [p for p in out if p["featured"]]
    if raycast_only:
        out = [p for p in out if p["raycast_friendly"]]
    if query:
        terms = [t for t in query.split() if t.strip()]
        scored = [(p, score_match(p, terms)) for p in out]
        scored.sort(key=lambda x: x[1], reverse=True)
        out = [p for p, s in scored if s > 0]
    return out[:limit]


def format_md(prompts: list[dict]) -> str:
    lines: list[str] = []
    for p in prompts:
        badges = []
        if p["featured"]:
            badges.append("⭐ Featured")
        if p["raycast_friendly"]:
            badges.append("🚀 Raycast")
        badge_str = f" ({', '.join(badges)})" if badges else ""
        lines.append(f"## {p['title']}{badge_str}\n")
        lines.append(f"- **id**: `{p['id']}`")
        lines.append(f"- **category**: {p['category']}")
        if p.get("author"):
            author_str = f"[{p['author']}]({p['author_url']})" if p.get("author_url") else p["author"]
            lines.append(f"- **author**: {author_str}")
        if p.get("source"):
            lines.append(f"- **source**: {p['source']}")
        if p.get("gallery_url"):
            lines.append(f"- **preview**: {p['gallery_url']}")
        if p.get("description"):
            lines.append(f"\n{p['description']}\n")
        lines.append("### Prompt\n")
        lines.append("```")
        lines.append(p["prompt"])
        lines.append("```\n")
        lines.append("---\n")
    return "\n".join(lines)


def format_summary(prompts: list[dict]) -> str:
    lines = [f"{len(prompts)} prompts matched:\n"]
    for p in prompts:
        flags = []
        if p["featured"]:
            flags.append("⭐")
        if p["raycast_friendly"]:
            flags.append("🚀")
        flag_str = "".join(flags) + " " if flags else ""
        lines.append(f"- [{p['id']}] {flag_str}{p['title']} ({p['category']})")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--query", "-q", help="Keyword search in title/description/prompt")
    parser.add_argument("--category", "-c", choices=sorted(CATEGORIES))
    parser.add_argument("--featured", action="store_true", help="Featured entries only")
    parser.add_argument("--raycast", action="store_true", help="Raycast-friendly entries only")
    parser.add_argument("--id", dest="prompt_id", help="Exact prompt ID lookup")
    parser.add_argument("--format", "-f", choices=["summary", "md", "json"], default="summary")
    parser.add_argument("--limit", "-l", type=int, default=20)
    args = parser.parse_args()

    data = load()
    results = filter_prompts(
        data["prompts"],
        query=args.query,
        category=args.category,
        featured_only=args.featured,
        prompt_id=args.prompt_id,
        raycast_only=args.raycast,
        limit=args.limit,
    )

    if args.format == "json":
        print(json.dumps(results, indent=2, ensure_ascii=False))
    elif args.format == "md":
        print(format_md(results))
    else:
        print(format_summary(results))
    return 0


if __name__ == "__main__":
    sys.exit(main())

variables.default:
export function parsePromptVariables(template: string): string[] {
  if (!template) return [];
  const regex = /\{\{([^}]+)\}\}/g;
  const matches = new Set<string>();
  let match: RegExpExecArray | null;
  while ((match = regex.exec(template)) !== null) {
    matches.add(match[1].trim());
  }
  return Array.from(matches);
}
